public class Document_title_TriageGen1Test {

    @Test
    public void testTitleWithValidTagAndText() {
        Document doc = Jsoup.parse("<html><head><title>  Hello World  </title></head><body></body></html>");
        assertEquals("Hello World", doc.title());
    }










}

